"use strict";

import * as Rights from "approot/global/references/rights.js";
import * as Roles from "approot/global/references/roles.js";

angular
	.module("irtech.netcity.school.main")
	.filter('htmlToPlaintext', function() {
		return function(text) {
			let retText = text ? String(text).replace(/<[^>]+>/gm, '').trim() : '';
			return retText;
		};
	})
	.filter('trusted', function ($sce) {
		return function (html) {
			return $sce.trustAsHtml(_.unescape(html));
		}
	})
	.controller("MainScreenCtrl", ($scope, $http, $document, $location, $appLoader, settingsProvider) => {

		$scope.$parent.page = {
			title: language.Generic.MenuFolders.kMainScreen
		}

		$scope.userId = appContext.userId;

		$scope.screenElementTypes= {
			diary: 1, // Дневник
			announcements: 2, // Объявления
			schedule: 3, // Расписание
			activities: 4, // Учебные курсы
			forum: 5, // Форум
			mail: 6, // Почта
			ege: 7, // Результаты ЕГЭ
			avgMarkDynReport: 8, // Отчет "Динамика среднего балла"
			totalMarksReport: 9, // Отчет "Итоговые оценки"
			parentInfoLetterReport: 10 // Отчет "Информационное письмо для родителей"
		}

		$.extend($scope, {
			data: {
				language: language,
				newMessagesAmount: null,
				lastAnnouncement: null,
				screenElements: null,
				studentTitle: _.intersection(appContext.roles, [Roles.student]).length > 0 ? "обучающегося" : "своего ребёнка"
			},
			state: {
				newMessagesReady: false,
				lastAnnouncementReady: false,
				screenElementsReady: false
			},
			ready: false

		});

		$scope.complementScreenElements = () => {
			var emptyList = !_.toArray($scope.data.screenElements).length;
			return _.map($scope.screenElementTypes, (item) => {
				var newElement = {
					screenElementType: item,
					order: $scope.data.screenElements[item] ? $scope.data.screenElements[item].order : item,
					visible: $scope.data.screenElements[item] || emptyList ? true : false
				}
				return newElement;
			});
		}

		$scope.isExistsRight = (screenElementType) => {
			switch (screenElementType) {
				case $scope.screenElementTypes.diary:
					return appContext.hasAnyRight([Rights.arAssignmentsViewComplete]) && (appContext.funcType !== 1);
				case $scope.screenElementTypes.announcements:
					return appContext.hasAnyRight([Rights.arAnnouncementView, Rights.arAnnouncementPost]);
				case $scope.screenElementTypes.schedule:
					return appContext.hasAnyRight([Rights.arCalendarViewSelf, Rights.arCalendarViewAll]);
				case $scope.screenElementTypes.activities:
					return appContext.hasAnyRight([Rights.arLAViewMaterials]) && (appContext.funcType !== 1) && $scope.LaIntegrationCourses;
				case $scope.screenElementTypes.forum:
					return appContext.hasAnyRight([Rights.arForumSendReceive]);
				case $scope.screenElementTypes.mail:
					return appContext.hasAnyRight([Rights.arMessagesSendReceive]);
				case $scope.screenElementTypes.ege:
					return $("ul.navbar-nav > li > ul > li:contains('Результаты ГИА')").length > 0;
				case $scope.screenElementTypes.avgMarkDynReport:
					return appContext.hasAnyRight([Rights.arReportsViewForAssignedClass, Rights.arReportsForAllClasses, Rights.arReportsForAssignedClass]) && (appContext.funcType !== 1);
				case $scope.screenElementTypes.totalMarksReport:
					return appContext.hasAnyRight([Rights.arReportsViewForAssignedClass, Rights.arReportsForAllClasses, Rights.arReportsForAssignedClass]) && (appContext.funcType !== 1);
				case $scope.screenElementTypes.parentInfoLetterReport:
					return appContext.hasAnyRight([Rights.arReportsViewForAssignedClass, Rights.arReportsForAllClasses, Rights.arReportsForAssignedClass]);
			}
			return false;
		}

		$scope.isVisible = (screenElementType) => {
			return $scope.data.screenElements ? $scope.data.screenElements[screenElementType].visible && $scope.isExistsRight(screenElementType) : false;
		}

		$scope.saveCheckMenuItems = () => {
			$http.post(`/webapi/users/${$scope.userId}/mainscreen`, {
				MainScreenElements: _.toArray(_.map(_.filter($scope.data.screenElements, (item) => item.visible), (element) => {
					var screenElement = {
						Order: element.order,
						ScreenElementType: element.screenElementType,
						Visible: element.visible
					}
					return screenElement;
				}))
			})
				.then((result) => {
				});
		}

		$scope.invertCheckMenuItem = (elementIndex) => {
			$scope.data.screenElements[elementIndex].visible = !$scope.data.screenElements[elementIndex].visible;
			$scope.stop(null, null);
		}

		// Получение количества новых сообщений
		$scope.loadNewMessagesAmount = () => {
			$scope.state.newMessagesReady = false;
			$http.get("/webapi/mail/messages/unreaded")
			.catch((response) => $alerts.error(response.data.message, response.data.details))
			.then((response) => {
				$scope.data.newMessagesAmount = response.data;
				$scope.state.newMessagesReady = true;
				$scope.$applyAsync(() => {});
				},
			() => $scope.state.newMessagesReady = false);
		}

		// Получение последнего объявления
		$scope.loadLastAnnouncement = () => {
			$scope.state.newMessagesReady = false;
			$http.get("/webapi/announcements", {params: { take: 2, fullVersion: false } })
			.catch((response) => $alerts.error(response.data.message, response.data.details))
			.then((response) => {
				$scope.data.announcements = response.data;
				$scope.state.announcementsReady = true;
				$scope.$applyAsync(() => { });
			},
			() => $scope.state.announcementsReady = false);
		}

		$scope.loadScreenElements = () => {
			$scope.state.newMessagesReady = false;
			$http.get(`/webapi/users/${$scope.userId}/mainscreen`)
			.catch((response) => $alerts.error(response.data.message, response.data.details))
			.then((response) => {
				$scope.data.screenElements = response.data ? _.indexBy(response.data, 'screenElementType') : response.data;
				$scope.data.screenElements = _.indexBy($scope.complementScreenElements(), 'screenElementType');
				$scope.state.screenElementsReady = true;
				$scope.$applyAsync(() => { $(".sortable > .item").sort($scope.sortByOrder).detach().appendTo($(".sortable")); });
			},
			() => $scope.state.screenElementsReady = false);
		}

		$scope.sortByOrder = (a, b) => {
			var result = 0;
			var index1 = a.id;
			var index2 = b.id;
			if (index1 && index2) {
				if ($scope.data.screenElements[+index1].order < $scope.data.screenElements[+index2].order) {
					result = -1;
				}
				if ($scope.data.screenElements[+index1].order > $scope.data.screenElements[+index2].order) {
					result = 1;
				}
			}
			return result;
		}

		$scope.stop = (event, element)  => {
			_.each(_.filter($(".ui-sortable-handle"), (item) => $scope.data.screenElements[+$(item).prop("id")].visible ),
				(item, index) =>
					$scope.data.screenElements[+item.id].order = index + 1);
			$scope.saveCheckMenuItems();
		}

		//загрузка данных
		$scope.load = () => {

			$("body").addClass("bg-lightgray");

			$(".reports.totals.item").on("click", () => postTo("/asp/Reports/ReportStudentTotalMarks.asp", { RPTID: "StudentTotalMarks", RPNAME: "Итоговые отметки" }));
			$(".reports.infomail.item").on("click", () => postTo("/asp/Reports/ReportParentInfoLetter.asp", { RPTID: "ParentInfoLetter", RPNAME: "Информационное письмо для родителей" }));
			$(".stat.item").on("click", () => postTo("/asp/Reports/ReportStudentAverageMarkDyn.asp", { RPTID: "StudentAverageMarkDyn", RPNAME: "Динамика среднего балла" }));

			$(".ege.item").on("click", () => postTo("/angular/school/gia/results/"));

			$(".mail.item").on("click", () => { sys.mail.inbox(); return false; });
			$(".schedule.item").on("click", () => { postTo("/asp/calendar/WeekViewTimeS.asp"); });
			$(".journal.item").on("click", () => { postTo("/angular/school/studentdiary/"); });
			$(".courses.item").on("click", () => { postTo("/angular/school/activities"); });
			$(".ads-all.link").on("click", () => { ShowAnnouncements(); return false; });
			$(document).on("click", ".item.ads .read-more", () => { ShowAnnouncements(); return false; });
			$(".forum.item").on("click", () => { ShowForum(); return false; });



			$(document).on('click', '.screen_menu .item_screenmenu.head', (event) => {
				$('.screen_menu').toggleClass('close open');
				//event.stopPropagation();
			});
			$(document).on('click', '.screen_menu label[for="item-data-1"]', (event) => {
				$scope.$applyAsync(() => { $scope.invertCheckMenuItem($scope.screenElementTypes.announcements) });
				event.stopPropagation();
			});
			$(document).on('click', '.screen_menu label[for="item-data-2"]', (event) => {
				$scope.$applyAsync(() => { $scope.invertCheckMenuItem($scope.screenElementTypes.mail) });
				event.stopPropagation();
			});
			$(document).on('click', '.screen_menu label[for="item-data-3"]', (event) => {
				$scope.$applyAsync(() => { $scope.invertCheckMenuItem($scope.screenElementTypes.diary) });
				event.stopPropagation();
			});
			$(document).on('click', '.screen_menu label[for="item-data-4"]', (event) => {
				$scope.$applyAsync(() => { $scope.invertCheckMenuItem($scope.screenElementTypes.schedule) });
				event.stopPropagation();
			});
			$(document).on('click', '.screen_menu label[for="item-data-5"]', (event) => {
				$scope.$applyAsync(() => { $scope.invertCheckMenuItem($scope.screenElementTypes.activities) });
				event.stopPropagation();
			});
			$(document).on('click', '.screen_menu label[for="item-data-6"]', (event) => {
				$scope.$applyAsync(() => { $scope.invertCheckMenuItem($scope.screenElementTypes.parentInfoLetterReport) });
				event.stopPropagation();
			});
			$(document).on('click', '.screen_menu label[for="item-data-7"]', (event) => {
				$scope.$applyAsync(() => { $scope.invertCheckMenuItem($scope.screenElementTypes.totalMarksReport) });
				event.stopPropagation();
			});
			$(document).on('click', '.screen_menu label[for="item-data-8"]', (event) => {
				$scope.$applyAsync(() => { $scope.invertCheckMenuItem($scope.screenElementTypes.forum) });
				event.stopPropagation();
			});
			$(document).on('click', '.screen_menu label[for="item-data-9"]', (event) => {
				$scope.$applyAsync(() => { $scope.invertCheckMenuItem($scope.screenElementTypes.ege) });
				event.stopPropagation();
			});
			$(document).on('click', '.screen_menu label[for="item-data-10"]', (event) => {
				$scope.$applyAsync(() => { $scope.invertCheckMenuItem($scope.screenElementTypes.avgMarkDynReport) });
				event.stopPropagation();
			});
			
			$scope.loadScreenElements();
			$scope.loadNewMessagesAmount();
			$scope.loadLastAnnouncement();

			settingsProvider.ServerSettings.SystemSettings.LaIntegrationCourses()
				.then(
					(val) => {
						$scope.LaIntegrationCourses = val;
				});
				
			setTimeout(() => $appLoader.hide(), 250);

			$(".sortable")
				.sortable({
					cursor: "move",
					revert: true,
					helper: 'clone',
					placeholder: "ui-state-highlight",
					//   delay: 150,
					//   distance: 5,
					scroll: true,
					scrollSensitivity: 100,
					opacity: 0.7,
					tolerance: "pointer",
					stop: $scope.stop
				});
			
		}

		$scope.load();
	});



