const module = angular.module("irtech.netcity.school.main",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap",
		"irtech.netcity.common", "irtech.netcity.ui-components"
	]);

require("./index/mainScreenCtrl.js");

module
	.filter("extension",
		() => {
			return (input) => {
				return input.split(".").pop();
			}
		})
	.config(($routeProvider, $locationProvider) => {
		$routeProvider
			.otherwise({
				templateUrl: "/static/dist/app/school/main/index/template.html",
				controller: "MainScreenCtrl"
			});

		$locationProvider.hashPrefix('');
		$locationProvider.html5Mode({
			enabled: true,
			requireBase: true
		});
	});


